import { spawn, SpawnOptions } from 'node:child_process';
import { Writable } from 'node:stream';

interface ShellOptions extends Partial<SpawnOptions> {
  echo?: boolean|{ stdout?: boolean|Writable|null, stderr?: boolean|Writable|null };
  shell?: boolean | string; // If string, use as shell command (e.g., 'ssh user@host')
}
interface MaybeWritable { stdout?: Writable|null, stderr?: Writable|null };
interface NormalizedShellOptions extends SpawnOptions {
  echo: MaybeWritable;
  shell?: boolean | string;
}

function normalizeShellOptions(options: Partial<ShellOptions>)
: NormalizedShellOptions {
  
  const opts: ShellOptions = { ...options };
  
  const normalizeWritable = (
    w: boolean|Writable|null|undefined,
    defaultWritable:Writable|null = null
  ): Writable|null => {
    if (w === true) return defaultWritable;
    if (w === false || w === undefined) return null;
    return w;
  }

  if (opts.echo === true) {
    opts.echo = { stdout: process.stdout, stderr: process.stderr };
  } else if (opts.echo === false || opts.echo === undefined) {
    opts.echo = { stdout: null, stderr: null };
  } else if (typeof opts.echo === 'object') {
    opts.echo.stdout = normalizeWritable(opts.echo.stdout, process.stdout);
    opts.echo.stderr = normalizeWritable(opts.echo.stderr, process.stderr);
  }
  return opts as NormalizedShellOptions;
}

function isTemplateStringsArray(
  strings: unknown
): strings is TemplateStringsArray {
  return Array.isArray(strings) && typeof (strings as any).raw !== 'undefined';
}

function reduceCommandLine(s:TemplateStringsArray, ...v:any[]): string {
  return s.reduce((acc, str, i) =>
    acc + str + (i < v.length ? String(v[i]) : ''), '');
}

/**
 * Parse a command line string into a command and arguments, taking quotes and
 * escaped spaces into account.
 * @param commandLine 
 * @returns command line split into a command and an array of arguments.
 * @throws Error if there are unmatched quotes in the command line.
 */
function commandLine(
  commandLineStrings: TemplateStringsArray,
  ...values: any[])
:{ command: string, args: string[] } {

  const commandLine = reduceCommandLine(commandLineStrings, ...values).trim();

  const args = [];
  let currentArg = '';
  let quoteType:string|null = null;
  let escapeNext = false;

  for (let i = 0; i < commandLine.length; i++) {
    const char = commandLine[i];

    if (escapeNext) {
      currentArg += char;
      escapeNext = false;
    } else if (char === '\\') {
      escapeNext = true;
    } else if (char === '"' || char === "'") {
      if (currentArg && quoteType === char) {
        // Closing quote
        quoteType = null;
      } else if (currentArg && quoteType !== null) {
        // Nested quote, treat as part of the argument
        currentArg += char;
      } else {
        // Opening quote
        quoteType = char;
      }
    } else if (char === ' ' && quoteType === null) {
      if (currentArg) {
        args.push(currentArg);
        currentArg = '';
      }
    } else {
      currentArg += char;
    }
  }

  if (currentArg) {
    args.push(currentArg);
  }

  if (quoteType !== null) {
    throw new Error('Unmatched quotes in command line');
  }

  return { command: args.shift() || '', args };
}

/**
 * Tagged template for live-shell execution with streaming output.
 */
function doSpawn(
  options: ShellOptions, 
  strings: TemplateStringsArray,
  ...values: any[]
): Promise<string> {

  const opts = normalizeShellOptions(options);
  
  const { command, args } = (() => {
    if (opts?.shell) {
      if (
        typeof opts.shell === 'string' &&
        opts.shell.substring(0, 4) === 'ssh '
      ) {
        const shellCommand = opts.shell;
        opts.shell = false; // Disable shell option for ssh
        return {
          command: 'ssh',
          args: shellCommand.substring(4).split(' ')
            .concat([reduceCommandLine(strings, ...values)]),
        }
      } else {
        return {
          command: reduceCommandLine(strings, ...values),
          args: [],
        };
      }
    } else {
      return commandLine(strings, ...values);
    }
  })();

  const subprocess = spawn(
    command, args,
    {...{stdio: 'pipe'}, ...opts}
  );

  let pipeData = { stdout: '', stderr: '' };
  let out = '';
  const outputPipe = (pipe:'stdout'|'stderr', force = false) => {
    if (pipeData[pipe]) {
      if (force) {
        if (opts.echo[pipe]) {
          opts.echo[pipe].write(pipeData[pipe]);
        }
        pipeData[pipe] = '';
      } else if (pipeData[pipe].indexOf('\n') >= 0) {
        const lines = pipeData[pipe].split('\n');
        if (opts.echo[pipe]) {
          for (let i = 0; i < lines.length - 1; i++) {
            opts.echo[pipe].write(lines[i] + '\n');
          }
        }
        pipeData[pipe] = lines[lines.length - 1];
      }
    }
  }
  const outputPipes = (force = false) => {
    outputPipe('stdout', force);
    outputPipe('stderr', force);
  }

  subprocess.stderr?.on('data', (data) => {
    pipeData.stderr += data.toString();
    outputPipe('stderr');
  });
  subprocess.stdout?.on('data', (data) => {
    const d = data.toString();
    pipeData.stdout += d;
    out += data.toString();
    outputPipe('stdout');
  });
  
  return new Promise((resolve, reject) => {
    subprocess.on('close', resolve);
    subprocess.on('error', reject);
  })
  .finally(outputPipes)
  .then(() => { 
    return out;
  });
}

type SpawnOptionsTemplateFunction =
  (strings: TemplateStringsArray, ...values: any[]) => Promise<string>;

function $(
  strings: TemplateStringsArray,
  ...values: any[]
): Promise<string>;
function $(
  options: ShellOptions
): SpawnOptionsTemplateFunction;

function $(
  strings: TemplateStringsArray|ShellOptions,
  ...values: any[]
): Promise<string>|SpawnOptionsTemplateFunction {
  if (isTemplateStringsArray(strings)) {
    return doSpawn({}, strings, ...values);
  } else if (typeof strings === 'object' && values.length === 0) {
    const options = strings as ShellOptions;
    const resultTemplateFunction:SpawnOptionsTemplateFunction =
      (s: TemplateStringsArray, ...v: any[]):Promise<string> => {
      return doSpawn(options, s, ...v);
    };
    return resultTemplateFunction;
  } else {
    throw new Error('Invalid arguments');
  }
}

export default $;
